 function equip(){let v=document.getElementById('command').value.trim().toLowerCase();let found=Object.keys(weapons).find(k=>k===v||weapons[k].name.toLowerCase().includes(v));if(found){weapon=weapons[found];document.getElementById('weaponName').innerHTML=weapon.name+' <span style="color:#888;font-size:11px">× equipped</span>';flash('ARMORY ONLINE',weapon.name+' requisitioned');document.getElementById('command').value=''}else if(v){flash('NO MATCH','try: ak · desert eagle · shotgun · smg');document.getElementById('command').value=''}}document.getElementById('command').addEventListener('keydown',e=>e.stopPropagation());
 function flash(a,b){let t=document.getElementById('toast');document.getElementById('toastTitle').textContent=a;document.getElementById('toastText').textContent=b;t.classList.add('show');clearTimeout(t._x);t._x=setTimeout(()=>t.classList.remove('show'),1800)}
-function nextWave(){wave++;enemies=[];spawnTimer=0;challengeTimer=0;challenge=null;flash('WAVE '+String(wave).padStart(2,'0'),wave%4===0?'something is wrong with the water':'the dead are learning');document.getElementById('wave').textContent=String(wave).padStart(2,'0')}
+function nextWave(){wave++;enemies=[];spawnTimer=0;challengeTimer=0;challenge=null;challengeDone=false;flash('WAVE '+String(wave).padStart(2,'0'),wave%4===0?'something is wrong with the water':'the dead are learning');document.getElementById('wave').textContent=String(wave).padStart(2,'0')}
 function startChallenge(){let type=['tsunami','tiger','pokemon'][(wave/3|0)%3];challenge={type,life:type==='tsunami'?5:10,x:type==='tsunami'?-100:W+70,y:type==='tsunami'?H*.7:H*.35};flash(type==='tsunami'?'WARNING: TSUNAMI':type==='tiger'?'APEX PREDATOR':'FIND THE POKEMON',type==='tsunami'?'DODGE THE WALL':'survive the surprise');}
 function spawn(){let side=Math.floor(Math.random()*4),x=side<2?(side?W+25:-25):Math.random()*W,y=side<2?Math.random()*H:(side?H+25:-25);let type=Math.random()<.14?'brute':'walker';enemies.push({x,y,r:type==='brute'?20:13,hp:type==='brute'?90+wave*5:35+wave*3,max:type==='brute'?90+wave*5:35+wave*3,speed:type==='brute'?22+wave:35+wave*2,type});}
 function shoot(){let now=performance.now();if(now-player.lastFire<weapon.rate)return;player.lastFire=now;let a=Math.atan2(mouse.y-player.y,mouse.x-player.x);player.bat=1;if(weapon.kind==='melee'){for(let e of enemies)if(Math.hypot(e.x-player.x,e.y-player.y)<95&&Math.abs(Math.atan2(Math.sin(Math.atan2(e.y-player.y,e.x-player.x)-a),Math.cos(Math.atan2(e.y-player.y,e.x-player.x)-a)))<1.5)e.hp-=weapon.damage;burst(player.x+Math.cos(a)*50,player.y+Math.sin(a)*50,'#c8f56a',5);return}let n=weapon.kind==='spread'?5:1;for(let i=0;i<n;i++){let aa=a+(Math.random()-.5)*(weapon.kind==='spread'?.45:.035);bullets.push({x:player.x+Math.cos(aa)*22,y:player.y+Math.sin(aa)*22,vx:Math.cos(aa)*weapon.speed,vy:Math.sin(aa)*weapon.speed,damage:weapon.damage,color:weapon.color||'#fff',life:60})}burst(player.x+Math.cos(a)*25,player.y+Math.sin(a)*25,weapon.color||'#fff',3)}
 function burst(x,y,c,n){for(let i=0;i<n;i++)particles.push({x,y,vx:(Math.random()-.5)*5,vy:(Math.random()-.5)*5,life:25,color:c})}

