-function update(dt,t){let dx=(keys.d?1:0)-(keys.a?1:0),dy=(keys.s?1:0)-(keys.w?1:0),l=Math.hypot(dx,dy)||1;player.x=Math.max(22,Math.min(W-22,player.x+dx/l*190*dt));player.y=Math.max(22,Math.min(H-22,player.y+dy/l*190*dt));if(mouse.down||keys[' '])shoot();player.bat=Math.max(0,player.bat-dt*4);spawnTimer-=dt;if(spawnTimer<=0&&enemies.length<Math.min(5+wave*2,22)){spawn();spawnTimer=Math.max(.22,1.05-wave*.035)}if(enemies.length===0&&spawnTimer<0&&challengeTimer<=0){if(wave%3===0&&!challenge)startChallenge();else nextWave()}for(let e of enemies){let a=Math.atan2(player.y-e.y,player.x-e.x),sp=e.speed*(challenge?.type==='tsunami'?1.1:1);e.x+=Math.cos(a)*sp*dt;e.y+=Math.sin(a)*sp*dt;if(Math.hypot(e.x-player.x,e.y-player.y)<e.r+player.r){player.hp-=18*dt;shake=5}}for(let b of bullets){b.x+=b.vx;b.y+=b.vy;b.life--;for(let e of enemies)if(e.hp>0&&Math.hypot(e.x-b.x,e.y-b.y)<e.r+5){e.hp-=b.damage;b.life=0;burst(e.x,e.y,b.color,4);if(e.hp<=0){score+=e.type==='brute'?40:10;burst(e.x,e.y,'#ff4d49',10)}}}bullets=bullets.filter(b=>b.life>0);enemies=enemies.filter(e=>e.hp>0);for(let p of particles){p.x+=p.vx;p.y+=p.vy;p.life--}particles=particles.filter(p=>p.life>0);if(challenge){challengeTimer+=dt;challenge.life-=dt;if(challenge.type==='tsunami'){challenge.x+=240*dt;if(challenge.x>W+140){challenge=null;challengeTimer=0}}else if(challenge.type==='tiger'){challenge.x-=130*dt;if(Math.hypot(challenge.x-player.x,challenge.y-player.y)<50)player.hp-=40*dt;if(challenge.x<-80){challenge=null;challengeTimer=0}}else{challenge.x-=75*dt;if(Math.hypot(challenge.x-player.x,challenge.y-player.y)<70){score+=200;flash('FOUND IT','the little creature is safe');challenge=null;challengeTimer=0}else if(challenge.x<-80){challenge=null;challengeTimer=0}}}if(player.hp<=0)gameOver();document.getElementById('threats').textContent=String(enemies.length).padStart(2,'0');document.getElementById('score').textContent=String(score).padStart(4,'0')}
+function update(dt,t){let dx=(keys.d?1:0)-(keys.a?1:0),dy=(keys.s?1:0)-(keys.w?1:0),l=Math.hypot(dx,dy)||1;player.x=Math.max(22,Math.min(W-22,player.x+dx/l*190*dt));player.y=Math.max(22,Math.min(H-22,player.y+dy/l*190*dt));if(mouse.down||keys[' '])shoot();player.bat=Math.max(0,player.bat-dt*4);spawnTimer-=dt;if(spawnTimer<=0&&enemies.length<Math.min(5+wave*2,22)){spawn();spawnTimer=Math.max(.22,1.05-wave*.035)}if(enemies.length===0&&spawnTimer<0&&challengeTimer<=0){if(wave%3===0&&!challenge&&!challengeDone)startChallenge();else if(!challenge)nextWave()}for(let e of enemies){let a=Math.atan2(player.y-e.y,player.x-e.x),sp=e.speed*(challenge?.type==='tsunami'?1.1:1);e.x+=Math.cos(a)*sp*dt;e.y+=Math.sin(a)*sp*dt;if(Math.hypot(e.x-player.x,e.y-player.y)<e.r+player.r){player.hp-=18*dt;shake=5}}for(let b of bullets){b.x+=b.vx;b.y+=b.vy;b.life--;for(let e of enemies)if(e.hp>0&&Math.hypot(e.x-b.x,e.y-b.y)<e.r+5){e.hp-=b.damage;b.life=0;burst(e.x,e.y,b.color,4);if(e.hp<=0){score+=e.type==='brute'?40:10;burst(e.x,e.y,'#ff4d49',10)}}}bullets=bullets.filter(b=>b.life>0);enemies=enemies.filter(e=>e.hp>0);for(let p of particles){p.x+=p.vx;p.y+=p.vy;p.life--}particles=particles.filter(p=>p.life>0);if(challenge){challengeTimer+=dt;challenge.life-=dt;if(challenge.type==='tsunami'){challenge.x+=240*dt;if(challenge.x>W+140){challenge=null;challengeTimer=0}}else if(challenge.type==='tiger'){challenge.x-=130*dt;if(Math.hypot(challenge.x-player.x,challenge.y-player.y)<50)player.hp-=40*dt;if(challenge.x<-80){challenge=null;challengeTimer=0}}else{challenge.x-=75*dt;if(Math.hypot(challenge.x-player.x,challenge.y-player.y)<70){score+=200;flash('FOUND IT','the little creature is safe');challenge=null;challengeTimer=0}else if(challenge.x<-80){challenge=null;challengeTimer=0}}}if(player.hp<=0)gameOver();document.getElementById('threats').textContent=String(enemies.length).padStart(2,'0');document.getElementById('score').textContent=String(score).padStart(4,'0')}
 function gameOver(){playing=false;document.getElementById('overlay').classList.remove('hidden');document.querySelector('.eyebrow').textContent='SIGNAL LOST // FINAL LOG';document.querySelector('.card h1').innerHTML='YOU<br>FELL';document.querySelector('.card p').innerHTML='The quarry keeps your name. Score: <em>'+score+'</em>. Restart and write your own way out.';document.getElementById('start').textContent='RESTART PROTOCOL →'}
 function draw(){ctx.save();if(shake){ctx.translate((Math.random()-.5)*shake,(Math.random()-.5)*shake);shake*=.9}ctx.fillStyle='#0b0c10';ctx.fillRect(0,0,W,H);let g=ctx.createRadialGradient(W/2,H/2,80,W/2,H/2,Math.max(W,H)*.75);g.addColorStop(0,'#1a1c20');g.addColorStop(1,'#08090c');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);ctx.strokeStyle='rgba(255,255,255,.045)';ctx.lineWidth=1;for(let x=0;x<W;x+=48){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke()}for(let y=0;y<H;y+=48){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke()}if(challenge?.type==='tsunami'){ctx.fillStyle='rgba(39,112,151,.68)';ctx.beginPath();ctx.moveTo(challenge.x,0);ctx.quadraticCurveTo(challenge.x+90,H*.25,challenge.x,H*.5);ctx.quadraticCurveTo(challenge.x-90,H*.75,challenge.x,H);ctx.lineTo(challenge.x-55,H);ctx.quadraticCurveTo(challenge.x+35,H*.7,challenge.x-20,H*.5);ctx.quadraticCurveTo(challenge.x+35,H*.25,challenge.x-55,0);ctx.fill()}for(let e of enemies){ctx.fillStyle=e.type==='brute'?'#6d2025':'#b6343a';ctx.beginPath();ctx.arc(e.x,e.y,e.r,0,7);ctx.fill();ctx.fillStyle='#08090c';ctx.beginPath();ctx.arc(e.x-4,e.y-2,2,0,7);ctx.arc(e.x+4,e.y-2,2,0,7);ctx.fill();ctx.fillStyle='#ff4d49';ctx.fillRect(e.x-e.r,e.y-e.r-8,e.r*2*(e.hp/e.max),2)}for(let b of bullets){ctx.fillStyle=b.color;ctx.beginPath();ctx.arc(b.x,b.y,3,0,7);ctx.fill()}for(let p of particles){ctx.globalAlpha=p.life/25;ctx.fillStyle=p.color;ctx.fillRect(p.x,p.y,3,3)}ctx.globalAlpha=1;if(challenge&&challenge.type!=='tsunami'){ctx.font='bold 34px Space Grotesk';ctx.fillStyle=challenge.type==='tiger'?'#d18b4e':'#f6dd64';ctx.fillText(challenge.type==='tiger'?'🐅':'⚡',challenge.x,challenge.y)}let a=Math.atan2(mouse.y-player.y,mouse.x-player.x);ctx.save();ctx.translate(player.x,player.y);ctx.rotate(a);ctx.fillStyle='#e7e1d7';ctx.beginPath();ctx.arc(0,0,player.r,0,7);ctx.fill();ctx.fillStyle='#80532f';if(weapon.kind==='melee'||player.bat){ctx.fillRect(8,-5,48,10)}else{ctx.fillRect(8,-4,25,8)}ctx.restore();ctx.strokeStyle='rgba(200,245,106,.18)';ctx.beginPath();ctx.arc(player.x,player.y,29,0,7);ctx.stroke();ctx.fillStyle='#ff4d49';ctx.fillRect(player.x-24,player.y+27,48*(player.hp/player.max),3);ctx.restore()}
 </script></body></html>
